% under the terms of the GNU General Public License as published by the Free
% Software Foundation; either version 2 of the License, or (at your option)
% any later version.

    tests = functiontests(localfunctions);
end

function testNestedStructVector(testCase)
    channels(1) = struct( ...
        'ChannelID', "channel-1", ...
        'ChannelName', "Vinculin", ...
        'FilePath', "/data/vinculin.tif");
    channels(2) = struct( ...
        'ChannelID', "channel-2", ...
        'ChannelName', "Actin", ...
        'FilePath', "/data/actin.tif");
    value = struct('AuxiliaryChannels', channels);

    expected = strjoin({ ...
        'AuxiliaryChannels:', ...
        '    (1):', ...
        '        ChannelID  : channel-1', ...
        '        ChannelName: Vinculin', ...
        '        FilePath   : /data/vinculin.tif', ...
        '    (2):', ...
        '        ChannelID  : channel-2', ...
        '        ChannelName: Actin', ...
        '        FilePath   : /data/actin.tif'}, newline);

    verifyEqual(testCase, matlabx.struct.prettyPrint(value), expected);
end

function testMatrixUsesSubscriptHeadings(testCase)
    value = repmat(struct('Value', 0), 2, 2);
    for k = 1:numel(value)
        value(k).Value = k;
    end

    expected = strjoin({ ...
        '(1,1):', '    Value: 1', ...
        '(2,1):', '    Value: 2', ...
        '(1,2):', '    Value: 3', ...
        '(2,2):', '    Value: 4'}, newline);
    verifyEqual(testCase, matlabx.struct.prettyPrint(value), expected);
end

function testFieldOrderIsPreserved(testCase)
    value = struct();
    value.First = 1;
    value.Child = struct('Value', 2);
    value.Last = 3;

    expected = strjoin({ ...
        'First: 1', ...
        'Child', ...
        '    Value: 2', ...
        'Last : 3'}, newline);
    verifyEqual(testCase, matlabx.struct.prettyPrint(value), expected);
end

function testEmptyStructArrayIncludesSize(testCase)
    value = repmat(struct('Value', 1), 0, 2);
    verifyEqual(testCase, matlabx.struct.prettyPrint(value), ...
        '[empty struct 0x2]');

    nested = struct('Items', value);
    verifyEqual(testCase, matlabx.struct.prettyPrint(nested), ...
        'Items: [empty struct 0x2]');
end
